#!/usr/bin/env bash
# Applies deploy/compose/kafka-acls.args (generated by scripts/gen-k8s-kafka.py from docs/security-mtls.md) to the compose broker.
# Runs inside the kafka image (acl-init service) with the admin certificate. Idempotent: --add of an existing ACL changes nothing.
set -euo pipefail

BOOTSTRAP=${BOOTSTRAP:-kafka:9093}
COMMAND_CONFIG=${COMMAND_CONFIG:-/pki/kafka-client.properties}
FILE=${ACLS_FILE:-/acls/kafka-acls.args}
KA=${KAFKA_ACLS:-/opt/kafka/bin/kafka-acls.sh}

set -f # the wildcard resource "*" must reach kafka-acls.sh as is
n=0
while read -r line; do
  [[ -z "$line" || "$line" == \#* ]] && continue
  # shellcheck disable=SC2086 # word splitting of the argument line is the point
  "$KA" --bootstrap-server "$BOOTSTRAP" --command-config "$COMMAND_CONFIG" --add $line </dev/null >/dev/null
  n=$((n + 1))
done <"$FILE"
echo "ACL rule groups applied: $n"
"$KA" --bootstrap-server "$BOOTSTRAP" --command-config "$COMMAND_CONFIG" --list </dev/null | grep -c 'principal=User:' | sed 's/^/ACL entries on the broker: /'
